import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Download, Eye, Maximize, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const WeeklyFocus = () => {
    const { user } = useAuth();
    const [isModalOpen, setIsModalOpen] = useState(false);

    // Use the public URL for the image
    const imageUrl = '/roadmapp.png';

    return (
        <div className="flex flex-col items-center justify-center w-full px-4 pb-10">
            
            {/* Header - CENTERED */}
            <div className="w-full max-w-5xl bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 rounded-2xl p-6 mb-6 text-white shadow-lg text-center">
                <h1 className="text-2xl md:text-3xl font-bold">
                    🚀 Full Stack + AI Roadmap
                </h1>
                <p className="text-blue-100 mt-1">Your 4-month journey to become a software engineer</p>
                
                {/* Buttons - Centered inside header */}
                <div className="flex justify-center gap-3 mt-4">
                    <button 
                        onClick={() => setIsModalOpen(true)}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                    >
                        <Maximize size={18} />
                        Full View
                    </button>
                    <button 
                        onClick={() => {
                            const link = document.createElement('a');
                            link.href = imageUrl;
                            link.download = 'FullStack_Roadmap.png';
                            link.click();
                        }}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                    >
                        <Download size={18} />
                        Download
                    </button>
                </div>
            </div>

            {/* Thumbnail Image - CENTERED */}
            <div 
                onClick={() => setIsModalOpen(true)}
                className="w-full max-w-5xl bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 overflow-hidden group cursor-pointer hover:shadow-2xl transition-all duration-300"
            >
                <div className="relative flex justify-center items-center w-full p-4">
                    <img 
                        src={imageUrl}
                        alt="Java Full Stack + AI Engineer Roadmap"
                        className="w-full h-auto max-h-[500px] object-contain bg-white dark:bg-gray-800 rounded-lg"
                        onError={(e) => {
                            console.error('Image failed to load:', imageUrl);
                            e.target.onerror = null;
                            e.target.style.display = 'none';
                            document.getElementById('image-error').style.display = 'block';
                        }}
                    />
                    
                    {/* Overlay on Hover */}
                    <div className="absolute inset-0 bg-black/40 bg-opacity-0 group-hover:bg-opacity-30 transition-all duration-300 flex items-center justify-center rounded-xl">
                        <div className="bg-white dark:bg-gray-800 rounded-full p-3 opacity-0 group-hover:opacity-100 transform scale-75 group-hover:scale-100 transition-all duration-300 shadow-lg">
                            <Maximize size={24} className="text-gray-800 dark:text-gray-200" />
                        </div>
                    </div>
                </div>
                
                <div id="image-error" style={{ display: 'none' }} className="text-center py-20 text-gray-500">
                    <p className="text-xl">⚠️ Image not found</p>
                    <p className="text-sm">Please make sure roadmapp.png is in the public folder</p>
                    <button 
                        onClick={() => window.location.reload()}
                        className="mt-4 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
                    >
                        Refresh
                    </button>
                </div>
            </div>

            {/* --- FULL SCREEN MODAL (POPUP) --- */}
            <AnimatePresence>
                {isModalOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 md:p-8"
                        onClick={() => setIsModalOpen(false)}
                    >
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.9, opacity: 0 }}
                            transition={{ type: "spring", damping: 25, stiffness: 300 }}
                            className="relative w-full h-full max-w-7xl max-h-[90vh] bg-white dark:bg-gray-900 rounded-2xl shadow-2xl overflow-hidden"
                            onClick={(e) => e.stopPropagation()}
                        >
                            {/* Modal Header */}
                            <div className="absolute top-0 left-0 right-0 z-10 p-4 bg-gradient-to-b from-black/50 to-transparent flex justify-between items-center">
                                <h3 className="text-white font-semibold text-lg">Full Stack + AI Roadmap</h3>
                                <button 
                                    onClick={() => setIsModalOpen(false)}
                                    className="text-white/80 hover:text-white bg-black/30 hover:bg-black/50 p-2 rounded-full transition"
                                >
                                    <X size={24} />
                                </button>
                            </div>

                            {/* Modal Image */}
                            <div className="w-full h-full overflow-auto p-4 pt-16 flex items-start justify-center bg-gray-50 dark:bg-gray-900">
                                <img 
                                    src={imageUrl}
                                    alt="Full Stack Roadmap"
                                    className="w-auto h-auto max-w-full object-contain rounded-lg shadow-md"
                                />
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Footer */}
            <div className="mt-6 text-center text-sm text-gray-400">
                Made by Swaliha • Keep Learning, Keep Growing! 🚀
            </div>
        </div>
    );
};

export default WeeklyFocus;
